// storage.bicep - a reusable module
param storageAccountName string
param location string = resourceGroup().location
param skuName string = 'Standard_LRS'

resource storageAccount 'Microsoft.Storage/storageAccounts@2023-05-01' = {
  name: storageAccountName
  location: location
  sku: {
    name: skuName
  }
  kind: 'StorageV2'
  properties: {
    accessTier: 'Hot'
  }
}

output storageAccountId string = storageAccount.id
output primaryBlobEndpoint string = storageAccount.properties.primaryEndpoints.blob

// main.bicep
param location string = resourceGroup().location

module devStorage './storage.bicep' = {
  name: 'devStorageDeployment'
  params: {
    storageAccountName: 'stdev${uniqueString(resourceGroup().id)}'
    location: location
    skuName: 'Standard_LRS'
  }
}

module prodStorage './storage.bicep' = {
  name: 'prodStorageDeployment'
  params: {
    storageAccountName: 'stprod${uniqueString(resourceGroup().id)}'
    location: location
    skuName: 'Premium_LRS'
  }
}

output devStorageId string = devStorage.outputs.storageAccountId
output prodStorageId string = prodStorage.outputs.storageAccountId
